params.query:
SELECT ?drug ?rel ?obj ?objLabel WHERE {
  ?drug rdfs:label "imatinib"@en .
  ?drug wdt:P31/wdt:P279* wd:Q12140 .          # instance of (a subclass of) medication
  VALUES ?rel { wdt:P129 wdt:P2175 }
  ?drug ?rel ?obj .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
